select p.OPERATION_ID,p.SOURCE_LOAD_OPERATION_ID,p.SOURCE_ST_ID,p.SOURCE_TT_ID,p.SOURCE_WARE_ID,
 p.TARGET_WARE_ID,coalesce(d.TARGET_TT_ID,p.TARGET_TT_ID) TARGET_TT_ID,nvl(p.SOURCE_PLACE_UID,p.ROOT_UID)PALLET_IDENTIFIER,p.ROOT_UID STOCK_PALLET_IDENTIFIER,p.INBOUND_DOCK,coalesce(d.OUTBOUND_DOCK,p.OUTBOUND_DOCK) OUTBOUND_DOCK,
 to_char(p.ARRIVAL_DUE,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') ARRIVAL_DUE,
 to_char(coalesce(d.READY_DUE,p.READY_DUE),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') READY_DUE,p.DECISION_REFERENCE,p.ACTOR,
 coalesce(th.REVISION_NO,0) TEMPERATURE_REVISION,th.DECISION_KIND TEMPERATURE_DECISION,th.OBSERVED_C,th.TASK_TEMP_MIN,th.TASK_TEMP_MAX,th.OPERATION_ID TEMPERATURE_OPERATION_ID,
 incident_close.OPERATION_ID INCIDENT_CLOSE_OPERATION_ID,incident_close.REASON_TEXT INCIDENT_CLOSE_REASON,incident_close.EVIDENCE_REFERENCE INCIDENT_CLOSE_EVIDENCE,
 to_char(incident_close.CLOSED_AT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM')INCIDENT_CLOSED_AT,
 p.TARGET_TT_ID ORIGINAL_TARGET_TRIP_ID,to_char(p.READY_DUE,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') ORIGINAL_READY_DUE,
 coalesce(d.REVISION_NO,0) DECISION_REVISION,d.DECISION_KIND,
 to_char(d.EXPECTED_ARRIVAL,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') EXPECTED_ARRIVAL,d.DECISION_REFERENCE LATEST_DECISION_REFERENCE,incident.INCIDENT_KIND,incident.INCIDENT_DETAIL,incident.EVIDENCE_REFERENCE,incident.OPERATION_ID INCIDENT_OPERATION_ID,case when r.CREATED_AT>incident.CREATED_AT then r.OPERATION_ID end INCIDENT_FOLLOWUP_RECEIPT_OPERATION_ID,
 source_leaf.ARTICLE ARTICLE,
 source_leaf.QUANTITY QUANTITY,
 source_leaf.BASE_UOM BASE_UOM,
 case when r.OPERATION_ID is not null then nvl(p.SOURCE_PLACE_UID,r.ROOT_UID)end RECEIVED_PALLET_IDENTIFIER,r.ROOT_UID RECEIVED_STOCK_IDENTIFIER,RRL_STOCK_PLAN_HELPER.decimal_text(r.BASE_QTY)RECEIVED_QUANTITY,
 RRL_STOCK_PLAN_HELPER.decimal_text(case when r.EXPECTED_BASE_QTY is not null then r.EXPECTED_BASE_QTY-r.BASE_QTY else 0 end)SHORT_QUANTITY,
 r.DISCREPANCY_REASON,r.DISCREPANCY_REFERENCE,
 t.TRANSPORT VEHICLE_NUMBER,u.OPERATION_ID UNLOAD_OPERATION_ID,r.OPERATION_ID RECEIPT_OPERATION_ID,
 f.TASK_ID PLACED_TASK_ID,active_plan.TASK_ID PLACEMENT_PLAN_TASK_ID,active_plan.TASK_STATUS PLACEMENT_PLAN_TASK_STATUS,c.OPERATION_ID CUSTODY_RELEASE_OPERATION_ID,b.ST_IDENTIFIER ONWARD_ST_IDENTIFIER,
 to_char(u.CREATED_AT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') UNLOADED_AT,
 to_char(r.CREATED_AT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') RECEIVED_AT,
 to_char(f.CREATED_AT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') PLACED_AT,
 to_char(systimestamp,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') OBSERVED_AT
from RRL_INTERWARE_PLAN p
left join RRL_INTERWARE_DECISION d on d.PLAN_OPERATION_ID=p.OPERATION_ID and d.REVISION_NO=(select max(z.REVISION_NO)from RRL_INTERWARE_DECISION z where z.PLAN_OPERATION_ID=p.OPERATION_ID)
left join RRL_INTERWARE_THERMAL_FACT th on th.PLAN_OPERATION_ID=p.OPERATION_ID and th.REVISION_NO=(select max(z.REVISION_NO)from RRL_INTERWARE_THERMAL_FACT z where z.PLAN_OPERATION_ID=p.OPERATION_ID)
left join RRL_INTERWARE_DECISION incident on incident.PLAN_OPERATION_ID=p.OPERATION_ID and incident.REVISION_NO=(select max(z.REVISION_NO)from RRL_INTERWARE_DECISION z where z.PLAN_OPERATION_ID=p.OPERATION_ID and z.INCIDENT_KIND is not null)
left join RRL_INTERWARE_INCIDENT_CLOSE incident_close on incident_close.INCIDENT_OPERATION_ID=incident.OPERATION_ID
join RRL_TRANSPORT_TASK t on t.ID=p.SOURCE_TT_ID
left join json_table(p.SOURCE_COMPOSITION_JSON,'$.nodes[*]'columns(
 UID_VALUE varchar2(200)path '$.uid',KIND_VALUE varchar2(20)path '$.kind',
 ARTICLE varchar2(160)path '$.article',QUANTITY varchar2(60)path '$.quantity',BASE_UOM varchar2(20)path '$.base_uom'))source_leaf
 on source_leaf.UID_VALUE=p.ROOT_UID and source_leaf.KIND_VALUE='STOCK'
left join RRL_INTERWARE_UNLOAD u on u.PLAN_OPERATION_ID=p.OPERATION_ID
left join RRL_INTERWARE_RECEIPT r on r.PLAN_OPERATION_ID=p.OPERATION_ID
left join(select ip.RECEIPT_OPERATION_ID,ip.TASK_ID,wt.STATUS TASK_STATUS from RRL_INTERWARE_PUT_PLAN ip join RRL_WAREHOUSE_TASK wt on wt.TASK_ID=ip.TASK_ID where wt.STATUS not in('DONE','CANCELLED')) active_plan on active_plan.RECEIPT_OPERATION_ID=r.OPERATION_ID
left join RRL_INTERWARE_PLACEMENT f on f.RECEIPT_OPERATION_ID=r.OPERATION_ID
left join RRL_INTERWARE_CUSTODY_PROOF c on c.RECEIPT_OPERATION_ID=r.OPERATION_ID
left join RRL_INTERWARE_ONWARD_BIND b on b.RECEIPT_OPERATION_ID=r.OPERATION_ID
where (p.SOURCE_WARE_ID=:ware or p.TARGET_WARE_ID=:ware)
 and (:history=1 or not exists(
  select 1 from RRL_TT_HU_LOAD_ST member_record join RRL_TT_HU_LOAD_FACT load_record on load_record.LOAD_OPERATION_ID=member_record.LOAD_OPERATION_ID
  where member_record.SBORKA_PALLET_ID=b.ST_ID and member_record.ACTIVE_FLAG=1 and load_record.STATUS='DEPARTED'
 ))
order by case when :history=1 then p.ARRIVAL_DUE end desc,p.ARRIVAL_DUE,p.OPERATION_ID fetch first 100 rows only
